WITH remaining_keys AS (SELECT id FROM suppliers EXCEPT DISTINCT SELECT id FROM suppliers WHERE rating > 2.4), kept_rows AS (SELECT s.* FROM suppliers s INNER JOIN remaining_keys k ON s.id = k.id) SELECT id, country, city, rating, CASE WHEN country RLIKE '^(DE|UK)$' THEN 'OTHER_ZONE' WHEN country RLIKE '^(TH|US)$' THEN 'EXTENDED' ELSE 'CORE' END AS country_zone FROM kept_rows ORDER BY id DESC NULLS FIRST, rating;
